using System;using System.Linq;using System.Collections.Generic;using MultiFPS.UI;using MultiFPS.Gameplay.RiftCombat;using ROM.Horde;using UnityEngine;using UnityEngine.UI;
namespace ROM.UI.Gameplay {
[DefaultExecutionOrder(1150)]public sealed class RiftMapRegionLevels:MonoBehaviour {
 public sealed class Region {public string Name;public int Minimum,Maximum;public Vector3 Center;public string Range=>"Nivel "+Minimum+(Minimum==Maximum?"":"–"+Maximum);}
 public IReadOnlyList<Region> Regions=>regions;readonly List<Region> regions=new List<Region>();readonly List<RectTransform> rows=new List<RectTransform>();readonly List<Rect> occupied=new List<Rect>();RiftFieldUI map;bool opened;float lastZoom=-1;int lastLevel=-1;Vector2 lastPlayer;
 public static Region[] ReadRegions(IEnumerable<RiftEnemySpawnZone> zones)=>zones.Where(z=>z&&!string.IsNullOrWhiteSpace(z.RegionTitle)).GroupBy(z=>z.RegionTitle.Trim()).Select(group=>new Region{Name=group.Key,Minimum=group.Min(z=>Mathf.Min(z.MinimumLevel,z.MaximumLevel)),Maximum=group.Max(z=>Mathf.Max(z.MinimumLevel,z.MaximumLevel)),Center=group.Aggregate(Vector3.zero,(sum,z)=>sum+z.transform.position)/group.Count()}).OrderBy(r=>r.Minimum).ThenBy(r=>r.Name).ToArray();
 void Awake(){map=GetComponent<RiftFieldUI>();}
 void LateUpdate(){if(!map||!map.MapOpen){opened=false;return;}if(!opened){Build();opened=true;lastZoom=-1;}var player=ClientFrontend.ClientPlayerInstance;var combat=player?player.GetComponent<AbilityController>():null;int level=combat?combat.Level:1;float zoom=map.Content.localScale.x;if(!Mathf.Approximately(lastZoom,zoom)||level!=lastLevel||Vector2.Distance(lastPlayer,map.PlayerMarker.anchoredPosition)>8){lastPlayer=map.PlayerMarker.anchoredPosition;Layout(zoom,level);lastZoom=zoom;lastLevel=level;}}
 void Build(){foreach(var row in rows)if(row)Destroy(row.gameObject);rows.Clear();regions.Clear();regions.AddRange(ReadRegions(FindObjectsByType<RiftEnemySpawnZone>(FindObjectsSortMode.None).Where(z=>z.gameObject.scene==UnityEngine.SceneManagement.SceneManager.GetActiveScene())));foreach(var region in regions){var root=new GameObject("Island levels: "+region.Name,typeof(RectTransform)).GetComponent<RectTransform>();root.SetParent(map.Content,false);root.anchorMin=root.anchorMax=root.pivot=new Vector2(.5f,.5f);root.sizeDelta=new Vector2(102,25);var bg=root.gameObject.AddComponent<RiftMapSurface>();bg.Fill=new Color(.025f,.025f,.045f,.9f);bg.Border=new Color(.43f,.37f,.53f,.9f);bg.Radius=4;bg.raycastTarget=true;
 var connector=new GameObject("Region range connector",typeof(RectTransform),typeof(Image)).GetComponent<Image>();connector.rectTransform.SetParent(root,false);connector.raycastTarget=false;connector.color=new Color(.8f,.68f,.9f,.4f);
 var text=new GameObject("Real island level range",typeof(RectTransform),typeof(Text)).GetComponent<Text>();text.rectTransform.SetParent(root,false);text.rectTransform.anchorMin=Vector2.zero;text.rectTransform.anchorMax=Vector2.one;text.rectTransform.offsetMin=new Vector2(3,0);text.rectTransform.offsetMax=new Vector2(-3,0);text.font=map.Theme.BodyFont;text.fontSize=12;text.alignment=TextAnchor.MiddleCenter;text.text=region.Range;text.raycastTarget=false;
 var tip=root.gameObject.AddComponent<RiftTooltipTrigger>();tip.Title=region.Name+" · "+region.Range;rows.Add(root);}}
 Rect OccupiedRect(RectTransform rect,float zoom){var corners=new Vector3[4];rect.GetWorldCorners(corners);var min=new Vector2(float.PositiveInfinity,float.PositiveInfinity);var max=new Vector2(float.NegativeInfinity,float.NegativeInfinity);foreach(var corner in corners){var point=(Vector2)map.Content.InverseTransformPoint(corner)*zoom;min=Vector2.Min(min,point);max=Vector2.Max(max,point);}return Rect.MinMaxRect(min.x-4,min.y-4,max.x+4,max.y+4);}
 void Layout(float zoom,int playerLevel){zoom=Mathf.Max(.01f,zoom);occupied.Clear();foreach(Transform child in map.Content){if(child.name.StartsWith("Island levels:"))continue;if(child.GetComponent<RiftTooltipTrigger>()){var pos=((RectTransform)child).anchoredPosition*zoom;occupied.Add(new Rect(pos-Vector2.one*14,Vector2.one*28));}foreach(var label in child.GetComponentsInChildren<Text>())if(label.enabled)occupied.Add(OccupiedRect(label.rectTransform,zoom));}if(map.PlayerMarker.gameObject.activeInHierarchy)occupied.Add(OccupiedRect(map.PlayerMarker,zoom));
 var choices=new List<Vector2>{new Vector2(0,25),new Vector2(0,-25),new Vector2(-30,30),new Vector2(30,-30),new Vector2(0,52),new Vector2(0,-52),new Vector2(-55,54),new Vector2(55,-54),new Vector2(-65,0),new Vector2(65,0),new Vector2(0,80),new Vector2(0,-80),new Vector2(-100,60),new Vector2(100,-60),new Vector2(-90,-90),new Vector2(90,90),new Vector2(0,110),new Vector2(0,-110)};for(int y=-220;y<=220;y+=20)for(int x=-220;x<=220;x+=20)choices.Add(new Vector2(x,y));
 for(int i=0;i<rows.Count;i++){var row=rows[i];var region=regions[i];bool valid=map.TryPosition(region.Center,out var position);row.gameObject.SetActive(valid);if(!valid)continue;var anchor=position*zoom;var size=row.sizeDelta;float best=float.PositiveInfinity;Vector2 chosen=anchor;
 foreach(var offset in choices){var candidate=anchor+offset;candidate.x=Mathf.Clamp(candidate.x,map.Content.rect.xMin*zoom+size.x*.5f,map.Content.rect.xMax*zoom-size.x*.5f);candidate.y=Mathf.Clamp(candidate.y,map.Content.rect.yMin*zoom+size.y*.5f,map.Content.rect.yMax*zoom-size.y*.5f);var bounds=new Rect(candidate-size*.5f,size);float penalty=0;foreach(var other in occupied)if(bounds.Overlaps(other))penalty+=10000+Mathf.Min(bounds.xMax,other.xMax)-Mathf.Max(bounds.xMin,other.xMin);penalty+=offset.sqrMagnitude*.001f;if(penalty<best){best=penalty;chosen=candidate;}}
 row.localScale=Vector3.one/zoom;row.anchoredPosition=chosen/zoom;occupied.Add(new Rect(chosen-size*.5f,size));var line=row.Find("Region range connector") as RectTransform;var delta=anchor-chosen;float distance=delta.magnitude;var direction=distance>.01f?delta/distance:Vector2.up;float edge=Mathf.Min(size.x*.5f/Mathf.Max(.001f,Mathf.Abs(direction.x)),size.y*.5f/Mathf.Max(.001f,Mathf.Abs(direction.y)));line.gameObject.SetActive(distance>edge+3);line.sizeDelta=new Vector2(Mathf.Max(0,distance-edge),1);line.anchoredPosition=direction*(distance+edge)*.5f;line.localRotation=Quaternion.Euler(0,0,Mathf.Atan2(direction.y,direction.x)*Mathf.Rad2Deg);var text=row.GetComponentInChildren<Text>();text.color=region.Minimum>playerLevel?new Color(1,.48f,.38f):region.Maximum>playerLevel?new Color(1,.78f,.45f):new Color(.92f,.84f,.64f);row.GetComponent<RiftTooltipTrigger>().Description=region.Range+(region.Minimum>playerLevel?"\nZona peligrosa para tu nivel.":"")+"\nAccesible: el rango informa la dificultad, no bloquea la entrada.";
 }
 }
}
}
